        bytes.extend_from_slice(fold.model_digest.as_array());
        bytes.extend_from_slice(fold.predictions_digest.as_array());
    }
    let plan_digest = Digest32::of_bytes(&bytes);
    Ok(CrossFoldPlanCommitmentsV2 {
        metric_contract_digest,
        plan_digest,
    })
}

